// ***************
// Filename: ddr_ctrl_regs_if.sv
// Author: FPGA Cores 4 U
// Description: Register interface of ddr_ctrl: joins the register map
//   ddr_ctrl_regs (modport regs) and the logic ddr_ctrl (modport core). cfg_*
//   go from the register map to the logic (register values, _wr write pulses,
//   _rd read pulses), sts_* come back (values read, _set / _clr hardware set
//   / clear pulses). A logic block ties every sts_* member it does not use to
//   0. Generated by ip/scripts/regmap_gen.py from ddr_ctrl_regs.json: edit
//   the JSON and regenerate.
// Date: 2026-10-21
interface ddr_ctrl_regs_if ();
  logic cfg_ctrl;
  logic cfg_ctrl_wr;
  logic [5-1:0] sts_status;
  logic [32-1:0] sts_rd_beats;
  logic [32-1:0] sts_wr_beats;
  logic [32-1:0] sts_acts;
  logic [32-1:0] sts_hits;
  logic [32-1:0] sts_refs;
  logic [32-1:0] sts_errs;

  modport regs (output cfg_ctrl, cfg_ctrl_wr, input sts_status, sts_rd_beats, sts_wr_beats, sts_acts,
    sts_hits, sts_refs, sts_errs);
  modport core (output sts_status, sts_rd_beats, sts_wr_beats, sts_acts, sts_hits, sts_refs, sts_errs, input
    cfg_ctrl, cfg_ctrl_wr);
  modport monitor (input cfg_ctrl, cfg_ctrl_wr, sts_status, sts_rd_beats, sts_wr_beats, sts_acts, sts_hits,
    sts_refs, sts_errs);
endinterface
